  VALUES 
    (250::BIGINT, 'Un profe bastante chill, solo con asistir y realizar las tareas sus evaluaciones son bastantes faciles y califica bastante suave'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '0ca53b416bd1d813079a833b13901601de484ac1338f842561ddcabf667edf47'::TEXT, ARRAY[3088]::BIGINT[]),
    (250::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3cce6c9abd07f0f924c00b2a4d8b8cd79c70345cb6b966360b995ee33c22eb59'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Las clases pueden ser pesadas pero el profe es demasiado carga explicando los temas. Los examenes se basaron en realizar proyectos y para la nota también importan los quices, los cuales él avisará siempre con una semana de antelación'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '76aaa660d12a86191986dabed6c3c48cc4c92c25dde2bd8462842e220d6238b5'::TEXT, ARRAY[3062]::BIGINT[]),
    (250::BIGINT, 'Muy buena persona, como profesor excelente, el curso hay que dedicarle tiempo, pero con las clases del profe y practicando bastante se pasa bien, al final la tematica es similar. Si no entienden algo pregunten, por lo general responde rápido el correo. Matricule sin miedo...'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3a5909f1d944643c1516eb56ecdcec38d718bf4590ba772611b35a2a9b86a4fa'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Es un excelente profesor, se le nota la pasión por enseñar, disfruta que le hagan preguntas, explica súper claro. Los únicos "contras" son que las clases son algo largas y el no dá recesos, o los dá pero muy cortos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'af1a9ba9404f40d3eab666d06aefa89c8677720e1722b0d2fbc64d4ad0976d49'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Excelente profesor, se le nota el gusto por enseñar. Brinda ayuda y el ambiente de clase se presta para sentirse cómodo de preguntar cualquier cosa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, '57a1b4d3c7d19d2261ad9e34929ab12b466a22f60aac7f6475bcb3e8ccb893ca'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Excelente profesor y persona. Motiva a aprender más. Le encanta que le pregunten y explica super claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, '3e5b6b1c3137966ed24d65606c95f17dd538343a0edd6e30765931fdca490140'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '632eb136744fc337fd77b6c05f90dd24eb4fe5f3e45e90d548b83d97bc4cae69'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Es un buen profesor. El curso se pasa solo con hacer los ejercicios recomendados y anotar cada ecuación o variante que usó para resolverlos. Algunos quices son fáciles otros no. Los examenes son ejercicios recomendados con una que otra modificación'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '454ae3c6dc7c3be47a653dd452a89e89fdf4b769ca441f0c1306589d22b6991b'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Sabe mucho de la materia y es buena gente, el problema es que no dice nada importante (habla mucha paja) . Como lo da el profe, el curso no es suficiente para diseñar sistemas de aire. De fijo pasa bien. Busque lo de semestres anteriores y está sobrado , si no hay que ser autodidacta. Es aburrido.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Muchos proyectos grupales']::TEXT[], '2021-01-10T00:00:00+00:00'::TIMESTAMPTZ, '618049c9be415d7f64b150c706974c024d0f34261602d4127cea2d998a78cfaf'::TEXT, ARRAY[107]::BIGINT[]),
    (250::BIGINT, 'El profe es muy bueno, da cada clase como si fuese presencial, el curso se pasa con resolver los ejercicios recomendados. Los exámenes virtuales estuvieron a un nivel medio de dificultad. Matricule sin miedo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '93765d299468fc0047add59647fe30466e6809b979a0bc41e48ea1d5666b372c'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'La materia no es díficil, los quices son fáciles, se resuelven con lo que el profe explica en la clase. Los exámenes virtuales estuvieron díficiles. El profe es muy claro, se preocupa por que uno entienda y le gusta dar el curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'e1df8388525b6a7e9a97d414230bacab17c4be43b56107ceba8f507ed5cdff13'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'La mayoría de temas del curso no son muy complicados y el profe explica muy bien la materia, aclara dudas si es necesario y es muy buena gente. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'dc6141494b43a4c254017a766a744a2d77a79dcff9b373e4876cd9e77d4a46c4'::TEXT, ARRAY[948]::BIGINT[]),
