    (250::BIGINT, 'Se preocupa por que entendamos'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '70364befa68df02ca812928b9473dc429551782842b0b244bb4473893b710f07'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Le apasiona el tema de ventilación industrial, por lo que se esforzó para que los estudiantes entendiéramos la materia y en consulta aclara todas las dudas que uno tenga, repite las explicaciones sin molestarse. En fin, excelente Profesor.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'a95422782287f97c1aaa1ef1e332feed341747814e69546f6900f70c90ca8b08'::TEXT, ARRAY[1501]::BIGINT[]),
