    (250::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'd05bdd6434662c2760eef39d0b8fc40ecfda101ffbbbfbe70ed8cdd01a65adbc'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Explica super claro, pero RAJADO tenés que hacer todos los ejercicios recomendados si quiere salir bien en el examen, trate de ir a consulta aunque sea saludarlo para que el vea su interés... Aproveche al 100% el primer parcial porque ese lo salva a uno de no reprobar.... Si quiere aprender matricul'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '8295e1b0b6352ea26ca366d71bdf18928540f9dc0eb32220536aa101d1ff2b35'::TEXT, ARRAY[948]::BIGINT[]),
