    (250::BIGINT, 'Excelente profesor explica demasiado bien y domina toda la materia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'c5d55513f4632bef84686433a504747fe3b0b53678eeccae955c52881006f031'::TEXT, ARRAY[948]::BIGINT[]),
