    (250::BIGINT, 'excelente profesor es una persona que transmite motivación para el curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '502b31a892ff4b78f43c315d4e51e2e0f067100331c6223b6d1be8d557c1e02a'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, '"Amen la termodinámica" Gran profesor, muy bueno. Muy buena gente también.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '44cfa2fe878484ee716a84c1f088653ffdc1f7407c1bb2d62e8a6c5f200f40ff'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Excelente profesor, excelente persona, siempre trata de ayudar a la clase si no les está yendo bien, explica clarisimo, revisa normal, sin duda uno de los mejores de la escuela de electromecánica, no se duda al matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd78b5499549c13efcf5984cb0073e50f9a9e065a33ce60c768207dfb43971bbd'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Sin duda uno de los mejores profesores, excelente explicando, a uno lo motiva mucho...'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'cb23504120c01913368befcb3d0170c82f61fe485bad4a8cc56b33d88245c8a6'::TEXT, ARRAY[948]::BIGINT[]),
    (250::BIGINT, 'Uno de los profes que me demostró que Mante es mi carrera. Le transmite a uno una energía para seguir estudiando. Como persona y profesor, uno de los mejores que he tenido en el Tec.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '62d5900e517466c5445558746dc37de53fb6feec6dfd7af0520dfa5fac48433c'::TEXT, ARRAY[948]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
